 <div class="sv-grid">${sv.map((s,i)=>`<article class="svc2" id="${s.slug}"><div class="sv-img imgrv"><img src="${esc(s.image)}" alt="${esc(s.name)}" loading="lazy" onerror="this.onerror=null;this.src='${esc(s.fallback||fb)}'"><span class="sv-no">${pn(i)}</span><span class="sv-ic"><i class="bi ${esc(s.icon||'bi-stars')}"></i></span></div><div class="sv-tx"><span class="eyebrow">Service ${pn(i)}</span><h2 class="rv">${esc(s.name)}</h2>${s.tagline?`<p class="sv-tag">${esc(s.tagline)}</p>`:''}<p class="lead">${esc(s.description)}</p><ul class="sv-b">${(s.benefits||[]).map(b=>`<li>${esc(b)}</li>`).join('')}</ul><div class="sv-act"><button class="btn-fw" data-svc="${s.id}">${esc(s.cta||'Enquire now')}</button><a class="btn-fw ghost" href="tel:${SITE.phoneTel}"><i class="bi bi-telephone"></i> Call us</a></div></div></article>`).join('')||'<p class="empty">No services published.</p>'}</div>
