 $('#gt').onclick=e=>{const b=e.target.closest('button');if(!b)return;cur=b.textContent;$$('#gt button').forEach(x=>x.classList.toggle('on',x===b));dr()};$('#gm').onclick=e=>{const f=e.target.closest('figure');if(f){sh(+f.dataset.idx);$('#lb').classList.add('on')}};
